            "h": "보만이 그린 두 그림 ②",
            "t": "보만은 이 대비의 근거를 히브리어 자체에서 찾았습니다. 예를 들어 \"있다\"를 뜻하는 히브리어 동사 **하야**는 가만히 \"존재한다\"보다 \"일어나다, 되다, 이루다\"에 가깝게 쓰인다고 보았습니다. 또 **다바르**라는 낱말이 \"말\"과 \"일(사건)\"을 함께 뜻하는 것은, 히브리 사람에게 말이 곧 일을 일으키는 힘이었기 때문이라고 설명했습니다.\n\n이 책은 널리 읽혔고, 오늘 교회에서 \"히브리적 사고\"라는 말이 퍼진 데에도 큰 몫을 했습니다. 성경을 우리 시대의 철학 틀로만 읽지 말자는 그의 문제의식은 지금도 귀합니다. 다만 그 방법에는 곧 날카로운 질문이 따라왔습니다."
