            "t": "사람은 누구나 머릿속에 세상의 그림을 하나 가지고 삽니다. 우리는 둥근 지구가 해 둘레를 돌고, 그 바깥에 끝없는 우주가 펼쳐진 그림을 떠올립니다. 학교에서 배워서, 굳이 생각하지 않아도 그 그림 안에서 하늘을 보고 날씨를 말합니다.\n\n고대 근동 사람들의 그림은 달랐습니다. 땅은 넓고 평평하며 그 아래와 둘레에 깊은 물이 있고, 하늘은 단단한 둥근 덮개처럼 땅 위를 덮어 그 위의 물을 막고 있다고 여겼습니다. 해와 달과 별은 그 덮개에 달린 빛이었습니다. 그리고 이 세상은 여러 신들이 다투고 다스리는 곳이었습니다.\n\n창세기 1장은 이 그림을 쓰는 사람들에게 처음 들렸습니다. 하나님은 그들이 알던 세상의 그림으로 말씀하시면서, 그 그림 안을 채우던 신들의 이야기를 완전히 바꾸셨습니다. 오늘은 \"세상을 보는 그림\"이라는 생각의 틀로 창세기 1장을 읽습니다."
