            "t": "우리는 관계를 흔히 마음의 문제로 생각합니다. 좋아하면 가까워지고, 마음이 멀어지면 멀어집니다. 그런데 구약 성경의 세계에서 중요한 관계는 마음만이 아니라 **언약**으로 맺어졌습니다. 언약은 말로 약속하고, 맹세하고, 표징을 세워 서로를 묶는 일이었습니다.\n\n구약에서 \"언약\"(베리트)은 수백 번 나옵니다. 사람과 사람 사이에도 언약을 맺었습니다. 아브라함과 블레셋 왕 아비멜렉이 우물을 두고 언약을 맺었고(창 21:27), 요나단과 다윗이 서로 목숨처럼 아끼며 언약을 맺었습니다(삼상 18:3). 예언자 말라기는 아내를 \"너와 맹약한 아내\"라고 부릅니다(말 2:14). 그리고 하나님은 노아와(창 9장), 아브라함과(창 15장, 17장), 시내산에서 이스라엘과, 그리고 다윗과(시 89:3) 언약을 맺으셨습니다.\n\n이 세계에서 \"관계가 있다\"는 것은 막연한 친밀감이 아니라 **서로에게 묶여 있다**는 뜻이었습니다. 누가 누구에게 무엇을 약속했고, 무엇을 지켜야 하며, 어기면 무슨 일이 일어나는지가 분명했습니다. 이 교재의 여러 과에서 보게 될 앎(5과), 공동체(7과), 바름(14과)도 이 언약이라는 틀 위에 서 있습니다."
