            "t": "\"독수리 날개로 너희를 업어\"는 하나님이 백성을 어떻게 이끄셨는지 보여 주는 그림입니다. 모세의 노래는 독수리가 새끼를 날개로 받쳐 업듯이 하나님이 이스라엘을 이끄셨다고 노래합니다(신 32:11). 언약은 이 돌봄 위에 세워집니다.\n\n5절의 \"내 소유\"(세굴라)는 그냥 가진 물건이 아니라 **특별히 아끼는 보물**을 말합니다. 다윗은 성전을 위해 자기 개인 보물(세굴라)을 내놓았다고 말합니다(대상 29:3). 온 세계가 다 하나님의 것이지만, 이스라엘은 그중에서도 하나님이 특별히 아끼시는 보배입니다.\n\n6절은 이 보배로운 백성의 사명을 말합니다. **제사장 나라**는 제사장이 하나님과 백성 사이에 서듯, 이스라엘이 하나님과 열방 사이에 서는 나라라는 뜻으로 풀이됩니다. 베드로는 이 말씀을 그리스도 안에 있는 교회에게 그대로 돌립니다. 너희는 택하신 족속이요 왕 같은 제사장들이요 거룩한 나라요 그의 소유가 된 백성이니(벧전 2:9).",
