            "t": "모세는 여호와의 말씀을 백성에게 전하고, 그 말씀을 다 기록합니다. 이튿날 제단을 쌓고 열두 기둥을 세운 뒤, 제물의 피 절반은 제단에 뿌리고, 언약서를 백성에게 읽어 들려줍니다. 백성이 \"여호와의 모든 말씀을 우리가 준행하리이다\"라고 답하자, 나머지 피를 백성에게 뿌리며 말합니다. 이는 여호와께서 이 모든 말씀에 대하여 너희와 세우신 **언약의 피**니라(24:8).\n\n피는 생명을 뜻합니다(레 17:11). 언약을 피로 세운다는 것은 이 묶임이 생명을 건 일이라는 뜻입니다. 그러나 이스라엘은 \"다 준행하리이다\"라는 약속을 지키지 못했습니다. 금송아지 사건(출 32장)이 곧바로 이어집니다. 예레미야는 훗날 하나님이 율법을 돌판이 아니라 마음에 새기는 **새 언약**을 세우실 것이라고 약속합니다(렘 31:31~34).\n\n예수님은 마지막 만찬에서 잔을 주시며 말씀하셨습니다. 이 잔은 내 피로 세우는 새 언약이니(눅 22:20). 시내산에서 짐승의 피로 세운 언약이, 그리스도께서 당신의 생명을 내어 주신 피로 새롭게 세워졌습니다. 사람이 지키지 못한 언약을 하나님이 그리스도 안에서 지키셨습니다.",
