            "h": "이름을 묻는다는 것",
            "t": "하나님이 모세를 이집트로 보내시려 하자 모세는 묻습니다. 백성이 그의 이름이 무엇이냐고 물으면 무엇이라고 대답해야 합니까(13절)? 성경에서 이름을 묻는 것은 부를 말을 알려는 것만이 아니라 \"당신은 누구이며 우리에게 어떤 분이 되어 주실 것인가\"를 묻는 일이었습니다. 얍복 나루의 야곱(창 32:29)과 삼손의 아버지 마노아(삿 13:17~18)도 이름을 물었지만 답을 듣지 못했습니다.\n\n그런데 하나님은 모세에게 답하십니다. \"에흐예 아셰르 에흐예.\" 우리말 성경은 이것을 \"나는 스스로 있는 자\"로 옮깁니다. \"에흐예\"는 1과에서 본 동사 **하야**(\"있다, 되다\")의 일인칭 꼴로, \"나는 ~이다\"로도 \"나는 ~일 것이다\"로도 읽힐 수 있습니다. 그래서 이 구절은 \"나는 있는 나다\", \"나는 내가 될 그대로 될 것이다\" 등 여러 가지로 옮겨집니다.⁵\n\n이 짧은 대답은 일부러 열어 둔 말처럼 들립니다. 하나님은 사람이 붙잡아 쓸 수 있는 이름표를 주시지 않습니다. 대신 \"내가 누구인지는 내가 하는 일을 통해 알게 될 것이다\"라고 말씀하시는 듯합니다."
