          {
            "id": "he04-r5",
            "kind": "read",
            "h": "그리스어 번역, 그리고 \"함께 있으리라\"",
            "t": "기원전 3세기 무렵부터 이집트 알렉산드리아의 유대인들은 히브리 성경을 그리스어로 옮겼습니다(칠십인역). 칠십인역은 14절을 \"나는 존재하는 자다\"로 옮겼고, 이 번역은 하나님을 \"변하지 않는 존재 자체\"로 생각하는 길을 열었습니다. 중세 신학자 토마스 아퀴나스는 이 구절을 들어 \"존재하는 자\"가 하나님께 가장 알맞은 이름이라고 했습니다.⁶ 이것은 \"히브리 사고가 그리스 사고에 오염되었다\"는 이야기가 아닙니다. 칠십인역을 만든 것은 유대인 자신들이었고, 하나님이 변하지 않으신다는 고백도 성경에 있습니다(말 3:6; 약 1:17).\n\n다만 출애굽기 3장이라는 이야기의 자리에서 이 이름은 먼저 **약속**으로 들렸습니다. 바로 앞 12절에서 모세가 \"내가 누구이기에\"라고 묻자 하나님은 \"내가 반드시 너와 **함께 있으리라**\"고 답하셨는데, 이 \"있으리라\"가 14절과 같은 \"에흐예\"입니다. 그래서 많은 해석자는 이 이름을 \"나는 너와 함께 있을 자다\"라는 뜻으로 듣습니다.⁵\n\n15절의 **여호와**(YHWH)도 같은 동사에서 온 이름으로 봅니다. 유대인들은 이 이름을 함부로 부르지 않으려고 \"아도나이\"(주)로 바꿔 읽었고, 그래서 본래 발음은 전해지지 않았습니다. 학자들은 \"야훼\"에 가까웠으리라 봅니다. \"여호와\"는 네 자음에 \"아도나이\"의 모음을 붙여 읽은 데서 생긴 말입니다."
          }
