            "t": "3:7~8에서 하나님은 동사로 당신을 소개하십니다. 내 백성의 고통을 분명히 **보고**, 부르짖음을 **듣고**, 근심을 **알고**, 그들을 건지려고 **내려가서**, 좋은 땅으로 **데려가려** 한다. 이름(14~15절)보다 이 동사들이 먼저 나옵니다. 하나님이 누구신지는 먼저 그분이 하시는 일로 드러나고, 이름은 그 일을 붙잡아 기억하게 합니다.\n\n여기서 하나님이 백성의 고통을 \"아신다\"는 것은 정보를 가지셨다는 말이 아니라, 그 고통을 당신의 일로 여기신다는 말입니다. 다음 과(5과)에서 \"듣다\"와 \"알다\"가 성경 세계에서 어떻게 관계와 행동으로 이어지는지 더 살펴봅니다. 2:24~25도 같은 말을 합니다. 하나님이 그들의 탄식을 듣고, 언약을 기억하시고, 돌아보시고, 아셨다. 3과에서 본 언약이 여기서 하나님을 움직입니다.\n\n그리고 이 동사들은 출애굽 사건으로 이어집니다. 훗날 이스라엘은 하나님을 소개할 때마다 이 일을 이야기했습니다. \"이집트에서 인도하여 내신 하나님\"은 구약에서 하나님을 부르는 가장 중요한 이름 가운데 하나가 되었습니다.",
