            "t": "모세의 첫 물음은 \"내가 누구이기에\"였습니다. 하나님은 모세가 얼마나 훌륭한지 말해 주지 않으십니다. 대신 \"내가 너와 함께 있으리라\"고 하십니다. 부르심에 맞는 자격은 부름 받은 사람에게서가 아니라 부르신 분의 함께하심에서 옵니다.\n\n15절에서 하나님은 당신을 아브라함, 이삭, 야곱의 하나님이라고 다시 소개하십니다. 새 이름은 옛 약속을 지우지 않습니다. 조상들과 함께하셨던 하나님이 이제 이 백성과 함께하실 것이고, 이 이름은 \"대대로 기억할 칭호\"가 됩니다. 하나님의 이름은 하나님이 함께 걸어오신 역사와 앞으로 함께 걸으실 약속을 함께 품습니다.\n\n신약 성경은 예수님을 \"임마누엘\", 곧 \"하나님이 우리와 함께 계시다\"라고 부릅니다(마 1:23). 또 요한복음에서 예수님은 \"아브라함이 나기 전부터 내가 있느니라\"고 말씀하십니다(요 8:58). 여기 쓰인 \"내가 있다\"(에고 에이미)는 출애굽기 3:14의 칠십인역과 같은 말로 시작합니다. 떨기나무 가운데서 약속하신 이름이 그리스도 안에서 사람의 얼굴로 왔습니다.",
