    "guide": "오늘의 생각의 틀은 \"성경은 몸과 마음과 영혼을 따로 떼지 않고 한 사람 전체로 본다\"는 것이에요. \"영혼이 따로 없다\"는 결론으로 흐르지 않게 들어가며의 \"조심할 것\"을 꼭 함께 읽어 주세요. 마음이 힘든 분이 있을 수 있으니 후렴을 함께 읽으며 위로를 나누는 시간을 넉넉히 가져 주세요.",
