            "t": "다니엘은 바빌론에서 예레미야의 칠십 년 예언을 읽고(단 9:2), 금식하며 기도합니다. 그 기도에는 \"우리\"가 가득합니다. 우리가 범죄하여 패역하며 행악하며 반역하여 주의 법도와 규례를 떠났사오며(9:5). 수치가 우리에게 돌아옴은 우리가 주께 범죄하였음이니이다(9:8).\n\n다니엘서는 다니엘을 사자 굴 앞에서도 하루 세 번 기도를 멈추지 않은 신실한 사람으로 그립니다(단 6:10). 그런 다니엘이 백성의 죄를 \"그들\"의 죄가 아니라 \"우리\"의 죄로 고백합니다. 느헤미야도 \"나와 내 아버지의 집이 범죄하였나이다\"라고 기도합니다(느 1:6). 공동체 안의 한 사람은 공동체의 죄를 남의 일로 보지 않습니다.\n\n다니엘의 기도는 이렇게 끝납니다. 우리가 주 앞에 간구하는 것은 우리의 공의를 의지하여 하는 것이 아니요 주의 큰 긍휼을 의지하여 함이오니(9:18). \"우리\"의 죄를 고백하는 기도는 \"우리\"를 향한 하나님의 긍휼을 구하는 기도로 이어집니다.",
