            "kind": "read",
            "h": "본문 설명 ③ · 한 사람이 많은 사람을 위하여",
            "t": "\"한 사람이 공동체를 대신하고, 공동체가 한 사람 안에서 하나가 된다\"는 생각은 성경의 가장 깊은 곳에 닿아 있습니다. 이사야 53장의 고난받는 종은 \"우리의 허물\" 때문에 찔리고 \"우리의 죄악\" 때문에 상합니다. 한 사람이 많은 사람의 죄를 짊어집니다.\n\n바울은 로마서 5장에서 아담과 그리스도를 나란히 놓습니다. 한 사람(아담)의 범죄로 많은 사람이 죄 아래 놓였듯이, 한 사람(그리스도)의 순종으로 많은 사람이 의인이 됩니다(롬 5:19). 교회는 아담이 모든 사람의 대표로 섰고, 그리스도께서 택하신 백성의 대표로 서셨다고 고백합니다(웨스트민스터 신앙고백 6장, 7장).\n\n아간 이야기에서 한 사람의 죄는 공동체 전체를 위태롭게 했습니다. 그리스도 안에서는 한 사람의 순종이 공동체 전체를 살립니다. 그래서 신약 성경은 그리스도인을 개인으로만이 아니라 \"그리스도 안에\" 있는 한 몸으로 부릅니다(고전 12:27).",
