            "t": "우리는 흔히 사람의 가치를 \"내가 나를 어떻게 여기는가\"로 생각합니다. 그런데 성경 세계에서 사람의 가치는 무엇보다 **공동체 앞에서** 매겨졌습니다. 다른 사람들이 나를 어떻게 보고 대하는지, 곧 명예와 수치가 사람의 자리를 정했습니다.\n\n구약에는 이 감각이 곳곳에 나옵니다. 아이를 낳지 못하던 라헬은 아들을 낳고 \"하나님이 나의 부끄러움을 씻으셨다\"고 말합니다(창 30:23). 암몬 왕은 다윗이 보낸 사신들의 수염 절반을 깎고 옷을 엉덩이까지 잘라 돌려보냈고, 다윗은 그들에게 수염이 자랄 때까지 여리고에 머물라고 합니다(삼하 10:4~5). 시인은 거듭 \"나를 부끄럽지 않게 하소서\"라고 기도합니다(시 25:2~3).\n\n이 장면들에서 부끄러움은 속마음의 죄책감만이 아니라, **사람들 앞에서 자리를 잃는 일**입니다. 성경 세계의 사람들에게 명예를 잃는 것은 때로 목숨을 잃는 것만큼 무거운 일이었습니다."
