            "t": "이사야 54장은 바빌론 포로기의 백성에게 주신 말씀입니다. 나라를 잃은 백성은 남편에게 버림받은 아내, 아이 없는 여인처럼 수치를 당하고 있었습니다. 하나님은 말씀하십니다. 두려워하지 말라, 네가 수치를 당하지 아니하리라. 너를 지으신 이는 네 남편이시라. 내가 잠시 너를 버렸으나 큰 긍휼로 너를 모을 것이요(54:4~7).\n\n신약 성경에서 이 수치의 이야기는 십자가에서 가장 깊은 곳에 닿습니다. 로마 세계에서 십자가는 가장 수치스러운 죽음이었습니다. 히브리서는 예수님이 \"그 앞에 있는 기쁨을 위하여 십자가를 참으사 **부끄러움을 개의치 아니하시더니**\"라고 말합니다(히 12:2). 신약학자 데이비드 드실바는 히브리서가 이렇게 세상이 주는 수치를 하나님이 주시는 명예로 다시 보게 한다고 보았습니다.⁵\n\n그리스도께서 우리의 수치를 대신 지셨기에, 바울은 이사야의 말씀을 이렇게 인용합니다. 누구든지 그를 믿는 자는 부끄러움을 당하지 아니하리라(롬 10:11; 사 28:16).",
