            "kind": "read",
            "h": "생각의 틀 · 하나님께 구별된 것",
            "t": "\"거룩\"이라고 하면 우리는 흔히 경건한 표정, 조용한 예배당, 도덕적으로 흠 없는 사람을 떠올립니다. 그런데 구약 성경에서 거룩은 무엇보다 **하나님께 구별된 것**을 뜻합니다. 하나님은 거룩하신 분이시고, 그분께 속하도록 따로 떼어 놓은 것이 거룩해집니다.\n\n그래서 구약에는 거룩한 것이 많습니다. 거룩한 땅(출 3:5), 거룩한 날(출 20:8), 거룩한 그릇과 옷(출 28~30장), 거룩한 백성(출 19:6). 이것들이 스스로 특별해서가 아니라 하나님께 속했기 때문에 거룩합니다. 성막은 바깥뜰, 성소, 지성소로 갈수록 더 거룩한 곳이 되었고, 그곳에 들어갈 수 있는 사람도 점점 줄었습니다.¹\n\n성경 세계의 사람들에게 세상은 거룩한 것과 속된 것, 정결한 것과 부정한 것이 구분되는 곳이었습니다. 이 구분은 하나님이 계신 곳을 중심으로 세상을 보는 방식이었습니다. 1과에서 본 느헤미야 8장의 백성이 율법책이 펴질 때 일어선 것도 이런 감각이었습니다.",
