            "t": "9~10절은 곡식을 거둘 때 밭 모퉁이까지 다 거두지 말고, 떨어진 이삭과 포도원의 떨어진 열매를 줍지 말고, 가난한 사람과 나그네를 위해 남겨 두라고 합니다. 이 말씀 끝에도 \"나는 너희 하나님 여호와이니라\"가 붙습니다. 내 밭의 소출을 다 거두지 않는 것이 하나님의 거룩에 참여하는 일입니다.\n\n14절은 귀먹은 사람을 저주하지 말고 눈먼 사람 앞에 장애물을 두지 말라고 합니다. 귀먹은 사람은 저주를 듣지 못하고, 눈먼 사람은 누가 장애물을 두었는지 보지 못합니다. 아무도 모를 것 같은 자리에서도 \"너는 하나님을 경외하라\"고 합니다. 거룩은 사람이 보지 않는 곳에서도 하나님 앞에서 사는 것입니다.\n\n그리고 18절, 원수를 갚지 말고 동포를 원망하지 말며 **네 이웃 사랑하기를 네 자신과 같이 사랑하라**. 예수님이 율법의 둘째 큰 계명으로 꼽으신 말씀(막 12:31)이 바로 레위기의 \"거룩 법\" 한가운데 있습니다.",
