            "t": "레위기의 세계에서 부정은 전염되는 것이었습니다. 부정한 것을 만지면 만진 사람도 부정해졌습니다(레 5:2~3). 그래서 피부병에 걸린 사람은 옷을 찢고 머리를 풀고 \"부정하다, 부정하다\" 외치며 진영 밖에 혼자 살아야 했습니다(레 13:45~46). 몸의 병보다 공동체에서 끊어지는 아픔이 더 컸을지도 모릅니다.\n\n마가복음에서 한 나병 환자가 예수님께 와서 \"원하시면 저를 깨끗하게 하실 수 있나이다\"라고 합니다. 예수님은 불쌍히 여기사 **손을 내밀어 그에게 대시며** \"내가 원하노니 깨끗함을 받으라\" 하십니다(막 1:41). 율법에 따르면 예수님이 부정해지셔야 했습니다. 그런데 거꾸로 그 사람이 깨끗해집니다. 열두 해 혈루증을 앓던 여인이 예수님의 옷에 손을 댔을 때도 마찬가지였습니다(막 5:25~34).\n\n예수님 안에서 거룩은 부정을 피해 숨지 않고, 부정한 사람에게 다가가 그를 깨끗하게 합니다. 히브리서는 그리스도께서 당신의 피로 우리 양심을 깨끗하게 하신다고 말합니다(히 9:13~14). 레위기의 정결법이 가리키던 것이 그리스도 안에서 이루어졌습니다.",
