            "t": "우리에게 역사는 흔히 \"지나간 일\"입니다. 교과서에 적힌 연도와 사건을 외우고, 시험이 끝나면 잊어버립니다. 그런데 성경 세계의 사람들에게 하나님이 하신 지난 일은 지나간 일로 끝나지 않았습니다. 그들은 그 일을 **기억하며 오늘 다시 살았습니다.**\n\n이스라엘의 절기가 그 예입니다. 유월절은 출애굽을 \"대대로 지킬 기념일\"이었고(출 12:14), 자녀가 \"이 예식이 무슨 뜻이냐\"고 물으면 부모는 그날 밤의 이야기를 들려주었습니다(출 12:26~27). 요단강을 건넌 뒤 이스라엘은 강바닥의 돌 열두 개로 기념비를 세웠는데, 훗날 자녀가 \"이 돌들은 무슨 뜻이냐\"고 물을 때 그날의 일을 들려주기 위해서였습니다(수 4:6~7). 시편 78편, 105편, 136편은 하나님이 하신 일을 처음부터 다시 노래합니다.\n\n이렇게 절기와 기념비와 노래로 지난 일을 되풀이해 기억하는 것은 성경 세계의 중요한 생각의 틀이었습니다. 기억은 머릿속의 회상이 아니라, 하나님이 하신 일 안으로 다시 들어가 그 일에 기대어 오늘을 사는 일이었습니다.",
