            "h": "기억이 일을 일으킨다",
            "t": "성경에서 기억은 자주 **행동**으로 이어집니다. \"기억하다\"(자카르)가 쓰인 자리를 보면 이것이 잘 드러납니다.¹\n\n하나님이 노아를 \"기억하시자\" 바람이 불어 물이 줄어들었습니다(창 8:1). 하나님이 라헬을 \"기억하시자\" 그의 태가 열렸습니다(창 30:22). 이스라엘이 이집트에서 부르짖을 때 하나님이 아브라함과 맺은 언약을 \"기억하셨고\"(출 2:24), 그 기억은 출애굽으로 이어졌습니다. 하나님이 잊고 계시다가 생각이 나셨다는 말이 아닙니다. 하나님이 약속하신 대로 이제 일하신다는 말입니다.\n\n사람의 기억도 마찬가지입니다. 안식일을 \"기억하여 거룩하게 지키라\"(출 20:8)는 계명은 날짜를 잊지 말라는 것이 아니라, 그날을 거룩하게 살라는 것입니다."
