            "t": "7~9절은 좋은 땅을 풍성하게 그립니다. 시내와 샘, 밀과 보리, 포도와 무화과와 석류, 감람나무와 꿀, 그리고 철과 구리가 나는 땅입니다. 하나님은 이 땅을 선물로 주십니다. 신명기는 풍요를 나쁜 것으로 보지 않습니다.\n\n위험은 풍요 자체가 아니라 풍요가 일으키는 잊음입니다. 그래서 10절은 단순한 처방을 줍니다. 먹어서 배부르면 좋은 땅을 주신 하나님을 **찬송하라**. 유대인들은 이 구절을 근거로 지금도 식사 뒤에 감사 기도를 드립니다. 감사는 기억을 지키는 습관입니다.\n\n17~18절은 마음속의 한 문장을 경계합니다. \"내 능력과 내 손의 힘으로 이 재물을 얻었다.\" 신명기는 이렇게 고쳐 말하라고 합니다. 재물 얻을 능력을 주신 이가 여호와시다. 기억은 내가 받은 것을 선물로 다시 보게 합니다.",
