            "t": "다윗은 나단의 이야기에 완전히 빠져들었습니다. 그는 크게 노하여 여호와의 살아 계심으로 맹세하며, 그런 일을 한 사람은 죽어 마땅하고 양을 네 배로 갚아야 한다고 판결합니다. 다윗의 정의감은 진심이었습니다. 다만 그 정의감이 남을 향해 있었을 뿐입니다.\n\n그때 나단이 말합니다. \"당신이 그 사람이라.\" 히브리어로는 두 낱말뿐인 짧은 말입니다. 이 한마디에 이야기 속 부자와 다윗이 겹쳐집니다. 많은 양을 가진 부자는 많은 아내를 둔 왕이고, 하나뿐인 암양은 우리아의 아내 밧세바입니다. 다윗은 방금 자기 입으로 자기에게 판결을 내린 것입니다.\n\n나단이 처음부터 \"당신은 간음하고 살인했다\"고 말했다면 어땠을까요? 다윗은 변명하거나 화를 냈을지도 모릅니다. 이야기는 다윗의 방어를 지나 그의 양심에 곧바로 닿았습니다.",
