            "t": "시편 23편의 목자는 낭만적인 그림이 아닙니다. 유대 광야의 목자는 물과 풀을 찾아 메마른 땅을 헤매고, 들짐승과 도둑에게서 양을 지켜야 했습니다. 다윗도 사자와 곰에게서 양을 지킨 목자였습니다(삼상 17:34~35). \"여호와는 나의 목자\"는 목숨을 맡긴다는 고백입니다. 그리고 앞에서 본 것처럼, 고대 근동에서 목자는 왕을 가리키는 그림이기도 했습니다.\n\n4절에서 시인은 사망의 음침한 골짜기를 다닐 때에도 해를 두려워하지 않는다고 합니다. 그 까닭은 골짜기가 사라져서가 아니라 \"주께서 나와 함께하심이라\"입니다. 여기서 시인은 하나님을 \"그\"에서 \"주\"(당신)로 바꾸어 부릅니다. 가장 어두운 곳에서 하나님을 가장 가까이 부릅니다.\n\n5절에서 그림은 집주인으로 바뀝니다. 원수가 보는 앞에서 상을 차려 주시고 머리에 기름을 부으시고 잔을 넘치게 하십니다. 손님을 극진히 대접하는 고대의 환대 그림입니다. 예수님은 \"나는 선한 목자라, 선한 목자는 양들을 위하여 목숨을 버리거니와\"라고 하셨습니다(요 10:11). 시편 23편의 목자가 그리스도 안에서 양을 위해 목숨을 내놓는 목자로 오셨습니다.",
