            "t": "이사야 40장은 바빌론 포로기의 지친 백성에게 주신 위로의 말씀입니다. 10~11절에서 하나님의 **팔**이 두 번 나옵니다. 한 번은 \"그의 팔로 친히 다스리실 것이라\"고 하고, 바로 다음 절에서 \"어린양을 그 팔로 모아 품에 안으시며 젖먹이는 암컷들을 온순히 인도하시리로다\"라고 합니다. 같은 팔이 다스리는 팔이면서 품는 팔입니다.\n\n12~26절에서 그림은 우주만큼 커집니다. 손바닥으로 바닷물을 헤아리시고, 뼘으로 하늘을 재시고, 땅에 사는 사람들은 메뚜기 같고, 열방은 통의 한 방울 물 같습니다. 바빌론이 섬기던 별들도 하나님이 하나하나 이름을 부르시는 피조물일 뿐입니다(26절, 2과 참조). 그 사이에 하나님은 거듭 물으십니다. 너희가 나를 누구에게 비기겠느냐(18, 25절).\n\n그리고 31절에서 이 크신 하나님이 지친 사람에게 내려오십니다. 오직 여호와를 앙망하는 자는 새 힘을 얻으리니 독수리가 날개 치며 올라감 같을 것이요. 3과에서 본 \"독수리 날개로 너희를 업어\"(출 19:4)가 여기서 다시 울립니다. 우주를 손바닥에 두신 하나님이 지친 한 사람을 날개로 들어 올리십니다.",
