            "lead": "지혜와 훈계를 알게 하고, 명철의 말씀을 깨닫게 하고, 공의와 정의와 정직을 행하게 하고, 어리석은 자를 슬기롭게 하는 것이에요. 젊은이만이 아니라 지혜 있는 자도 더 배운다고 해요(5절). 이 모든 것의 근본이 여호와를 경외함이라는 점을 짚어 주세요."
