            "t": "1. Nelson Glueck, *Das Wort hesed im alttestamentlichen Sprachgebrauche als menschliche und göttliche gemeinschaftsgemässe Verhaltungsweise* (박사 논문, Jena, 1927); 영어판 *Hesed in the Bible*, trans. Alfred Gottschalk (Cincinnati: Hebrew Union College Press, 1967).\n2. Katharine Doob Sakenfeld, *The Meaning of Hesed in the Hebrew Bible: A New Inquiry*, Harvard Semitic Monographs 17 (Missoula: Scholars Press, 1978).\n3. Gordon R. Clark, *The Word Hesed in the Hebrew Bible*, Journal for the Study of the Old Testament Supplement Series 157 (Sheffield: JSOT Press, 1993).\n4. 이 논의를 정리한 글로 Robin Routledge, \"Hesed as Obligation: A Re-examination,\" *Tyndale Bulletin* 46 (1995)을 볼 것.\n5. Hermann Cremer, *Die paulinische Rechtfertigungslehre im Zusammenhange ihrer geschichtlichen Voraussetzungen* (Gütersloh: Bertelsmann, 1899).\n6. Mark A. Seifrid, \"Righteousness Language in the Hebrew Scriptures and Early Judaism,\" in *Justification and Variegated Nomism*, vol. 1, *The Complexities of Second Temple Judaism*, ed. D. A. Carson, Peter T. O'Brien, and Mark A. Seifrid (Tübingen: Mohr Siebeck; Grand Rapids: Baker Academic, 2001).\n7. Charles Lee Irons, *The Righteousness of God: A Lexical Examination of the Covenant-Faithfulness Interpretation*, WUNT 2/386 (Tübingen: Mohr Siebeck, 2015)."
