            "id": "he16-r2",
            "kind": "read",
            "h": "샬롬을 읽는 법",
            "t": "메노나이트 구약학자 페리 요더는 『샬롬』(1987)에서 성경이 샬롬을 세 방향으로 쓴다고 정리했습니다.¹ 몸과 살림이 넉넉한 물질적 안녕, 사람 사이의 바른 관계와 정의, 그리고 정직하고 흠 없는 도덕적 온전함입니다. 그리고 이 셋이 서로 떨어지지 않는다고 보았습니다. 요더는 신약의 \"평안\"(에이레네)도 구약의 샬롬과 거의 같은 넓은 뜻으로 쓰인다고 보았습니다.\n\n샬롬을 설명할 때 \"샬롬의 뿌리 낱말이 '완전하게 하다'라는 뜻이므로 샬롬은 완전함이다\"라는 말을 자주 듣습니다. 샬롬과 \"온전하게 하다, 갚다\"가 같은 뿌리인 것은 사실입니다. 그러나 1과에서 배운 바의 경고처럼, 뜻은 뿌리가 아니라 쓰임이 정합니다. 샬롬이 넓은 뜻을 가진다면 그것은 뿌리 때문이 아니라 성경이 실제로 샬롬을 그렇게 넓게 쓰기 때문입니다.\n\n이 교재가 열여섯 과 내내 지켜 온 약속이 이것입니다. 생각의 틀은 낱말 하나에서가 아니라 성경이 실제로 말하고 그리는 수많은 장면에서 찾습니다."
