            "t": "두 제자는 슬픈 얼굴로 엠마오로 가고 있었습니다. 그들은 예수님이 이스라엘을 속량할 분이라고 바랐는데(21절), 그분이 십자가에서 죽으셨으니 그 바람도 끝났다고 생각했습니다. 14과에서 본 고엘, 곧 값을 치르고 되찾아 주는 분을 기다렸지만 하나님의 방법을 몰랐습니다. 예수님은 그들에게 모세와 모든 선지자의 글로 시작해 모든 성경에 쓴 바 자기에 관한 것을 **풀어** 주십니다(27절). 그리고 뒤에 다른 제자들에게도 \"그들의 마음을 열어 성경을 깨닫게\" 하십니다(45절).\n\n1과를 기억해 봅시다. 느헤미야 8장에서 레위 사람들은 율법책을 읽으며 뜻을 풀어 백성이 깨닫게 했고, 백성은 들은 말씀을 밝히 알았기 때문에 크게 즐거워했습니다(느 8:8, 12). 엠마오 길에서 예수님은 스스로 그 일을 하십니다. 제자들은 고백합니다. 길에서 우리에게 말씀하시고 성경을 풀어 주실 때에 우리 속에서 마음이 뜨겁지 아니하더냐(32절). 신약학자 리처드 헤이스는 이 엠마오 이야기를 실마리로, 복음서 기자들이 부활의 빛 아래서 이스라엘의 성경을 다시 읽었다고 보았습니다.²\n\n제자들의 눈이 밝아진 것은 예수님이 떡을 가지고 축사하시고 떼어 주실 때였습니다(30~31절). 10과에서 본 \"나를 기념하라\"의 식탁이 떠오릅니다. 그리고 그들은 그 즉시 일어나 밤길을 되돌아 예루살렘으로 가서 다른 제자들에게 이 일을 전합니다(33~35절). 깨달음은 공동체로 돌아가 함께 나누는 것으로 이어집니다.",
